import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"“加班”银行阻碍了共同富裕","description":"","frontmatter":{"title":"“加班”银行阻碍了共同富裕","sidebarTitle":"加班银行与共同富裕","date":"2026-03-31T00:00:00.000Z","category":"置身事内","tags":["企业观察"],"order":7},"headers":[],"relativePath":"articles/zstn/firm/zhaohang.md","filePath":"articles/zstn/firm/zhaohang.md","articleMeta":{"updated":"2026-03-31","words":1243,"minutes":3}}`),a={name:`articles/zstn/firm/zhaohang.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>2026年3月30日，招商银行董事长在2025年度业绩发布会上说：</p><blockquote><p>我们同事很少准点下班</p><p>周五公布完业绩后，这么厚一本材料，（周末）两天时间全部搞出来了。</p><p>这就是公司文化</p><p>我觉得这是最大的护城河</p></blockquote><p>招商银行的护城河竟然是加班文化，和“996是福报”有异曲同工之妙。想必这位董事长也是身居高位久了，和一位消失在公众视野的故人一样，大放厥词，视劳动法为无物，视劳动者为草芥。</p><p>博主认为，加班文化恰恰是阻碍共同富裕的绊脚石，加班内卷，一会带来岗位的下降、失业人口增加，二是岗位上的人看似获得了1.5倍甚至更高的工资，但失去时间、失去消费和家庭，打击宏观经济循环和生育率。</p><p>因此，博主的结论就是：以加班文化为护城河的招商银行，就是共同富裕的绊脚石。</p><p>私以为，招商银行的护城河，并不敢真的亮相——</p><p>2024年之前，招商银行会公布私人银行客户情况，通过Gemini查询数据如下：</p><table tabindex="0"><thead><tr><th><strong>年份</strong></th><th><strong>私人银行客户数（万户）</strong></th><th><strong>客户数同比增速</strong></th><th><strong>私行总资产（万亿元）</strong></th><th><strong>资产同比增速</strong></th><th><strong>户均资产（万元）</strong></th></tr></thead><tbody><tr><td><strong>2018</strong></td><td>7.29</td><td>13.19%</td><td>2.04</td><td>14.80%</td><td>2796</td></tr><tr><td><strong>2019</strong></td><td>8.17</td><td>11.98%</td><td>2.23</td><td>9.40%</td><td>2731</td></tr><tr><td><strong>2020</strong></td><td>10.00</td><td>22.41%</td><td>2.77</td><td>24.36%</td><td>2775</td></tr><tr><td><strong>2021</strong></td><td>12.21</td><td>22.09%</td><td>3.39</td><td>22.32%</td><td>2780</td></tr><tr><td><strong>2022</strong></td><td>13.48</td><td>10.43%</td><td>3.79</td><td>11.74%</td><td>2813</td></tr></tbody></table><p>这是招行引以为傲的数字，招行高净值人群的各项核心指标呈现出非常强劲的增长态势。在这五年间，招行私行客户数和总资产几乎翻了一倍。特别是在2020年和2021年，无论是客户数量还是管理的资产规模，均保持了超过20%的罕见高增速。</p><p>同时，人民群众也看到极致的“二八定律”甚至“一九定律”，<strong>私人银行客户</strong>仅占招行全行零售客户总数的<strong>0.07%</strong>，却持有了全行 <strong>31.28% ** 的零售财富。如果将统计范围扩大到</strong>金葵花及以上客户** （资产在50万元以上），这部分人占比约为<strong>2.2%</strong> ，却掌握了招行超过 <strong>81%</strong> 的零售资产。而占比高达 <strong>97.8%</strong> 的普通客户（资产50万以下），人均资产仅为1.25万元左右。</p><p>正是因为招行的这组数据过于精准、赤裸地描绘了财富金字塔的尖端状况，2023年年报开始，相关细节数据从财报上消失，不再披露。</p><p>两年后的今天，2025年业绩发布会上，招行董事长为什么不敢再介绍引以为傲的零售和私行？庞大的高净值人群不才是你真正的护城河吗？！</p><p>如果先富的人连财产规模都不敢亮出来，那又谈何先富带动后富，实现共同富裕。</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};